if (!defined('ABSPATH')) { exit; }
add_action('init',function(){if(get_option('bhc_snowa_reconcile_v358_done'))return;$pairs=[963=>1662,964=>1663,1162=>1664,960=>1665];$keys=['_bhc_source_url','_bhc_source_type','_bhc_source_checked_at','_bhc_catalog_quality_state','_bhc_verification_status','_bhc_specs','_bhc_no_price_message','_yoast_wpseo_metadesc','_bhc_image_generation_status','_bhc_image_prompt','_bhc_image_checked_at'];foreach($pairs as $target=>$duplicate){$src=get_post($duplicate);$dst=get_post($target);if(!$src||!$dst)continue;wp_update_post(['ID'=>$target,'post_title'=>$src->post_title,'post_content'=>$src->post_content,'post_excerpt'=>$src->post_excerpt]);$p=wc_get_product($target);if($p){$p->set_status('publish');$p->set_catalog_visibility('visible');$p->set_stock_status('outofstock');$p->save();}foreach($keys as $key){$value=get_post_meta($duplicate,$key,true);if($value!==''&&$value!==[])update_post_meta($target,$key,$value);}wp_set_object_terms($target,'اسنوا','pa_brand',true);$cat=wp_get_post_terms($duplicate,'product_cat',['fields'=>'ids']);if($cat)wp_set_object_terms($target,$cat,'product_cat',false);$aid=get_post_thumbnail_id($duplicate);if($aid){wp_update_post(['ID'=>$aid,'post_parent'=>$target]);set_post_thumbnail($target,$aid);}delete_post_thumbnail($duplicate);wp_update_post(['ID'=>$duplicate,'post_status'=>'trash']);}update_option('bhc_snowa_reconcile_v358_done',1,false);});
